("steps", [("Sodium chloride", "Na (2, 8, 1) &rarr; Na<sup>+</sup> (2, 8) + e<sup>&minus;</sup>; Cl (2, 8, 7) + e<sup>&minus;</sup> &rarr; Cl<sup>&minus;</sup> (2, 8, 8). The ions combine to form NaCl."), ("Magnesium chloride", "Mg (2, 8, 2) &rarr; Mg<sup>2+</sup> + 2e<sup>&minus;</sup>; each of two Cl atoms gains one electron, giving MgCl<sub>2</sub>.")]),
